<?php
declare(strict_types=1);require __DIR__.'/../app/bootstrap.php';if(is_file(__DIR__.'/../app/access_control_v1300.php'))require_once __DIR__.'/../app/access_control_v1300.php';require_once __DIR__.'/../app/classifieds_v1370.php';require_once __DIR__.'/../app/layout.php';if(!sk1370_admin()){http_response_code(403);exit('Forbidden');}$msg='';$err='';$pdo=sk1370_db();$tid=sk1370_tid();if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{sk1370_csrf_check();$action=(string)($_POST['action']??'');$id=(int)($_POST['ad_id']??0);if($action==='ad.approve'){$days=max(7,min(180,(int)sk1370_setting('classifieds_expiry_days','30')));$pdo->prepare("UPDATE classified_ads_v1370 SET status='active',moderation_status='approved',rejection_reason=NULL,published_at=COALESCE(published_at,NOW()),expires_at=DATE_ADD(NOW(),INTERVAL ".$days." DAY),bump_at=NOW(),updated_at=NOW() WHERE tenant_id=? AND id=?")->execute([$tid,$id]);$msg='Ad approved.';}elseif($action==='ad.reject'){$reason=trim((string)($_POST['reason']??'Not approved'));$pdo->prepare("UPDATE classified_ads_v1370 SET status='rejected',moderation_status='rejected',rejection_reason=?,updated_at=NOW() WHERE tenant_id=? AND id=?")->execute([$reason,$tid,$id]);$msg='Ad rejected.';}elseif($action==='ad.suspend'){$pdo->prepare("UPDATE classified_ads_v1370 SET status='suspended',updated_at=NOW() WHERE tenant_id=? AND id=?")->execute([$tid,$id]);$msg='Ad suspended.';}elseif($action==='report.resolve'){$rid=(int)($_POST['report_id']??0);$pdo->prepare("UPDATE classified_reports_v1370 SET status='resolved',resolved_by=?,resolved_at=NOW() WHERE tenant_id=? AND id=?")->execute([sk1370_uid(),$tid,$rid]);$msg='Report resolved.';}elseif($action==='promotion.approve'){$pid=(int)($_POST['promotion_id']??0);$q=$pdo->prepare('SELECT * FROM classified_promotions_v1370 WHERE tenant_id=? AND id=? LIMIT 1');$q->execute([$tid,$pid]);$p=$q->fetch(PDO::FETCH_ASSOC);if(!$p)throw new RuntimeException('Promotion request not found.');$days=max(1,min(30,(int)($_POST['days']??7)));if($p['promotion_type']==='featured')$pdo->prepare('UPDATE classified_ads_v1370 SET featured_until=DATE_ADD(NOW(),INTERVAL ".$days." DAY),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$tid,$p['ad_id']]);elseif($p['promotion_type']==='urgent')$pdo->prepare('UPDATE classified_ads_v1370 SET urgent_until=DATE_ADD(NOW(),INTERVAL ".$days." DAY),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$tid,$p['ad_id']]);else $pdo->prepare('UPDATE classified_ads_v1370 SET bump_at=NOW(),updated_at=NOW() WHERE tenant_id=? AND id=?')->execute([$tid,$p['ad_id']]);$pdo->prepare("UPDATE classified_promotions_v1370 SET status='approved',approved_by=?,approved_until=DATE_ADD(NOW(),INTERVAL ".$days." DAY),updated_at=NOW() WHERE tenant_id=? AND id=?")->execute([sk1370_uid(),$tid,$pid]);$msg='Promotion approved.';}else throw new RuntimeException('Unknown action.');try{if(function_exists('sk1300_audit'))sk1300_audit('classified.admin.'.$action,['id'=>$id]);}catch(Throwable $e){}}catch(Throwable $e){$err=$e->getMessage();}}$loadErr='';try{$stats=sk1370_admin_stats();}catch(Throwable $e){$stats=['all'=>0,'active'=>0,'pending'=>0,'sold'=>0,'reported'=>0];$loadErr='Statistics: '.$e->getMessage();}$filter=(string)($_GET['filter']??'pending');$where="a.tenant_id=?";$args=[$tid];if($filter==='pending')$where.=" AND a.moderation_status='pending'";elseif($filter==='active')$where.=" AND a.status='active' AND a.moderation_status='approved'";elseif($filter==='reported')$where.=" AND EXISTS(SELECT 1 FROM classified_reports_v1370 r WHERE r.tenant_id=a.tenant_id AND r.ad_id=a.id AND r.status='open')";elseif($filter==='sold')$where.=" AND a.status='sold'";try{$q=$pdo->prepare('SELECT a.*,c.name category_name FROM classified_ads_v1370 a JOIN classified_categories_v1370 c ON c.id=a.category_id WHERE '.$where.' ORDER BY a.created_at DESC LIMIT 200');$q->execute($args);$ads=$q->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){$ads=[];$loadErr=$loadErr?:('Ads: '.$e->getMessage());}try{$rq=$pdo->prepare("SELECT r.*,a.title,a.slug FROM classified_reports_v1370 r JOIN classified_ads_v1370 a ON a.id=r.ad_id AND a.tenant_id=r.tenant_id WHERE r.tenant_id=? AND r.status='open' ORDER BY r.created_at DESC LIMIT 100");$rq->execute([$tid]);$reports=$rq->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){$reports=[];$loadErr=$loadErr?:('Reports: '.$e->getMessage());}try{$pq=$pdo->prepare("SELECT p.*,a.title FROM classified_promotions_v1370 p JOIN classified_ads_v1370 a ON a.id=p.ad_id AND a.tenant_id=p.tenant_id WHERE p.tenant_id=? AND p.status='requested' ORDER BY p.requested_at ASC LIMIT 100");$pq->execute([$tid]);$promos=$pq->fetchAll(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){$promos=[];$loadErr=$loadErr?:('Promotions: '.$e->getMessage());}page_start('Classifieds Marketplace',true);?><link rel="stylesheet" href="/assets/classifieds-v1370.css?v=1370"><div class="skc-admin"><section class="admin-hero"><div><span>LOCAL CLASSIFIEDS · v13.7.0</span><h1>Marketplace Control Center</h1><p>Moderation, reports, promotions, categories and marketplace health.</p></div><div><a href="/classifieds.php" target="_blank">Open Marketplace</a><a href="/admin/classifieds-settings.php">Settings & Categories</a></div></section><?php if($loadErr):?><div class="notice err"><b>Classifieds data warning:</b> <?=sk1370_h($loadErr)?></div><?php endif;?><?php if($msg):?><div class="notice ok"><?=sk1370_h($msg)?></div><?php endif;?><?php if($err):?><div class="notice err"><?=sk1370_h($err)?></div><?php endif;?><div class="admin-kpis"><?php foreach(['all'=>'All Ads','active'=>'Active','pending'=>'Pending','sold'=>'Sold','reported'=>'Reported'] as $k=>$v):?><a href="?filter=<?=$k?>"><b><?=number_format($stats[$k]??0)?></b><span><?=$v?></span></a><?php endforeach;?></div><section class="admin-panel"><header><div><h2><?=sk1370_h(ucfirst($filter))?> Ads</h2><p>Review title, category, seller and description before publishing.</p></div></header><div class="admin-table"><table><thead><tr><th>Ad</th><th>Seller</th><th>Status</th><th>Created</th><th>Actions</th></tr></thead><tbody><?php foreach($ads as $a):?><tr><td><b><?=sk1370_h($a['title'])?></b><small><?=sk1370_h($a['category_name'])?> · <?=sk1370_h(sk1370_price_label($a))?> · <?=sk1370_h($a['area'])?></small></td><td><?=sk1370_h(sk1370_user_label((int)$a['user_id']))?></td><td><span class="status <?=sk1370_h($a['status'])?>"><?=sk1370_h($a['status'])?> / <?=sk1370_h($a['moderation_status'])?></span></td><td><?=sk1370_h($a['created_at'])?></td><td><div class="action-row"><a href="/classified.php?ad=<?=urlencode($a['slug'])?>&preview=1" target="_blank">Preview</a><?php if($a['moderation_status']!=='approved'):?><form method="post"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="ad.approve"><input type="hidden" name="ad_id" value="<?=$a['id']?>"><button>Approve</button></form><?php endif;?><form method="post" class="reject-form"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="ad.reject"><input type="hidden" name="ad_id" value="<?=$a['id']?>"><input name="reason" placeholder="Reject reason"><button>Reject</button></form><form method="post"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="ad.suspend"><input type="hidden" name="ad_id" value="<?=$a['id']?>"><button> Suspend </button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><div class="admin-two"><section class="admin-panel"><h2>Open Reports</h2><?php if(!$reports):?><p class="muted">No open reports.</p><?php endif;foreach($reports as $r):?><article class="admin-mini"><div><b><?=sk1370_h($r['title'])?></b><span><?=sk1370_h($r['reason'])?> · <?=sk1370_h($r['note'])?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="report.resolve"><input type="hidden" name="report_id" value="<?=$r['id']?>"><button>Resolve</button></form></article><?php endforeach;?></section><section class="admin-panel"><h2>Promotion Requests</h2><?php if(!$promos):?><p class="muted">No pending requests.</p><?php endif;foreach($promos as $p):?><article class="admin-mini"><div><b><?=sk1370_h($p['title'])?></b><span><?=sk1370_h($p['promotion_type'])?></span></div><form method="post"><input type="hidden" name="_csrf" value="<?=sk1370_h(sk1370_csrf())?>"><input type="hidden" name="action" value="promotion.approve"><input type="hidden" name="promotion_id" value="<?=$p['id']?>"><input type="number" name="days" min="1" max="30" value="7"><button>Approve</button></form></article><?php endforeach;?></section></div></div><?php page_end();
